// B"H
// Generates worker-bundle.js from worker_src/*.
//
// The engine worker used to be assembled at runtime into a blob: URL, but the
// site CSP blocks blob: workers (worker-src falls back to script-src 'self',
// no blob:), so `new Worker(blobUrl)` threw and the inspector could never
// load a model. The same code now ships as this static same-origin file.
// Re-run after editing worker_src/*:
//   node build-worker-bundle.mjs
import { readFileSync, writeFileSync } from 'node:fs';

// Same sources, same order as the worker call in app.js.
const SOURCES = [
  'worker_src/base.js',
  'worker_src/env.js',
  'worker_src/worker_main.js',
  'worker_src/gguf_parser.js',
  'worker_src/vocab/priority_queue.js',
  'worker_src/vocab/spm.js',
  'worker_src/tokenizer.js',
  'worker_src/model_loader.js',
  'worker_src/math_kernels.js',
  'worker_src/quant_common.js',
  'worker_src/quant_legacy.js',
  'worker_src/quant_k.js',
  'worker_src/quant_iq.js',
  'worker_src/math_stats.js',
  'worker_src/math_act.js',
  'worker_src/math_pos.js',
  'worker_src/tensor.js',
  'worker_src/config.js',
  'worker_src/weights.js',
  'worker_src/model_attn.js',
  'worker_src/model_ffn.js',
  'worker_src/model_block.js',
  'worker_src/loop.js',
  'worker_src/asm_common.js',
  'worker_src/asm_kernels.js',
  'worker_src/asm.js',
  'worker_src/math_wasm.js',
  'worker_src/purifier.js',
];

// Same extraction the old blob builder did on each function body: the code
// between the arrow-function braces.
function extractBody(rel) {
  const src = readFileSync(new URL(rel, import.meta.url), 'utf8');
  const arrow = src.search(/=>\s*\{/);
  if (arrow === -1) throw new Error(`No arrow-function body in ${rel}`);
  const start = src.indexOf('{', arrow);
  const end = src.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error(`Cannot extract body from ${rel}`);
  return src.slice(start + 1, end);
}

const parts = SOURCES.map(extractBody);
const header = `// B"H
// Generated by build-worker-bundle.mjs - do not edit by hand.
// Static engine-worker bundle. Re-run \`node build-worker-bundle.mjs\`
// after changing worker_src/*.
`;
writeFileSync(new URL('./worker-bundle.js', import.meta.url), header + parts.join('\n'));
console.log(`Wrote worker-bundle.js from ${parts.length} sources.`);
